// ════════════════════════════════════════════════════════════
//  INFRASTRUCTURE / PERSISTENCE
//  localStorage como capa de infraestructura.
//  Guardamos solo los IDs de clases reservadas por usuario,
//  no todo el objeto — más eficiente y menos riesgo de datos
//  desincronizados si cambian los datos base.
// ════════════════════════════════════════════════════════════

const PersistenceService = {
  // Clave única por usuario para no mezclar datos entre cuentas
  key: (userId) => `gym_enrollments_${userId}`,

  // Lee los IDs de clases donde el usuario está inscrito
  load: (userId) => {
    try {
      const raw = localStorage.getItem(PersistenceService.key(userId));
      return raw ? JSON.parse(raw) : null; // null = no hay datos guardados (primera vez)
    } catch {
      return null; // JSON corrupto → ignorar y usar estado base
    }
  },

  // Guarda el array de classIds donde el usuario está inscrito
  save: (userId, enrolledClassIds) => {
    try {
      localStorage.setItem(PersistenceService.key(userId), JSON.stringify(enrolledClassIds));
    } catch {
      // localStorage lleno o bloqueado → operación silenciosa
    }
  },

  clear: (userId) => {
    try { localStorage.removeItem(PersistenceService.key(userId)); } catch {}
  },
};

/**
 * Hidrata las clases base con los datos persistidos del usuario.
 * Si no hay datos guardados, usa el estado base (para la demo).
 * Recalcula availableSpots tras aplicar los cambios.
 */
function hydrateClasses(userId) {
  const saved = PersistenceService.load(userId);
  if (saved === null) return MOCK_CLASSES_BASE; // primera vez, usar base

  // Reconstruir enrolled de todas las clases aplicando los cambios del usuario
  return MOCK_CLASSES_BASE.map(c => {
    // ¿El usuario estaba en el enrolled base (otros usuarios)?
    const othersEnrolled = c.enrolled.filter(id => id !== userId);
    // ¿Tenemos guardado que este usuario está en esta clase?
    const userIsIn = saved.includes(c.id);
    const newEnrolled = userIsIn ? [...othersEnrolled, userId] : othersEnrolled;
    return { ...c, enrolled: newEnrolled, availableSpots: c.capacity - newEnrolled.length };
  });
}

// ════════════════════════════════════════════════════════════
//  CORE / SERVICES
// ════════════════════════════════════════════════════════════

const AuthService = {
  login: (email, password) => new Promise((res, rej) => {
    setTimeout(() => {
      const user = MOCK_USERS.find(u => u.email === email);
      if (user && password === MOCK_PASSWORD) res(user);
      else rej(new Error("Credenciales incorrectas"));
    }, 900);
  }),
  register: (name, email, password) => new Promise((res, rej) => {
    setTimeout(() => {
      if (MOCK_USERS.find(u => u.email === email)) { rej(new Error("Email ya registrado")); return; }
      const newUser = createUser({ id:`u${Date.now()}`, name, email, plan:"basic", joinDate:new Date().toISOString().split("T")[0], trainingDays:0 });
      MOCK_USERS.push(newUser);
      res(newUser);
    }, 1000);
  }),
};

const ClassService = {
  toggleBooking: (classes, classId, userId) => {
    return classes.map(c => {
      if (c.id !== classId) return c;
      const alreadyEnrolled = c.enrolled.includes(userId);
      if (!alreadyEnrolled && c.availableSpots <= 0) throw new Error("No hay plazas disponibles");
      const newEnrolled = alreadyEnrolled
        ? c.enrolled.filter(id => id !== userId)
        : [...c.enrolled, userId];
      return { ...c, enrolled: newEnrolled, availableSpots: c.capacity - newEnrolled.length };
    });
  },
};

// ════════════════════════════════════════════════════════════
//  STATE / CONTEXTS
// ════════════════════════════════════════════════════════════

const AuthContext = createContext(null);
const authReducer = (s, a) => {
  switch (a.type) {
    case "LOGIN_START":   return { ...s, loading:true, error:null };
    case "LOGIN_SUCCESS": return { ...s, loading:false, user:a.payload };
    case "LOGIN_ERROR":   return { ...s, loading:false, error:a.payload };
    case "LOGOUT":        return { user:null, loading:false, error:null };
    default: return s;
  }
};
function AuthProvider({ children }) {
  const [state, dispatch] = useReducer(authReducer, { user:null, loading:false, error:null });
  const login    = useCallback(async (email, pw) => {
    dispatch({ type:"LOGIN_START" });
    try { dispatch({ type:"LOGIN_SUCCESS", payload: await AuthService.login(email,pw) }); }
    catch(e) { dispatch({ type:"LOGIN_ERROR", payload:e.message }); }
  }, []);
  const register = useCallback(async (name, email, pw) => {
    dispatch({ type:"LOGIN_START" });
    try { dispatch({ type:"LOGIN_SUCCESS", payload: await AuthService.register(name,email,pw) }); }
    catch(e) { dispatch({ type:"LOGIN_ERROR", payload:e.message }); }
  }, []);
  const logout = useCallback(() => dispatch({ type:"LOGOUT" }), []);
  return <AuthContext.Provider value={{ ...state, login, register, logout }}>{children}</AuthContext.Provider>;
}
const useAuth = () => useContext(AuthContext);

// ─── GymContext — ahora con persistencia ────────────────────
const GymContext = createContext(null);
const gymReducer = (s, a) => {
  switch (a.type) {
    case "HYDRATE":        return { ...s, classes: a.payload };         // carga inicial desde storage
    case "TOGGLE_BOOKING": return { ...s, classes: a.payload };
    case "SET_ERROR":      return { ...s, bookingError: a.payload };
    case "CLEAR_ERROR":    return { ...s, bookingError: null };
    default: return s;
  }
};

function GymProvider({ children }) {
  const { user } = useAuth();
  const [state, dispatch] = useReducer(gymReducer, { classes: MOCK_CLASSES_BASE, bookingError:null });

  // EFECTO DE HIDRATACIÓN
  // Cuando el usuario cambia (login/logout), rehidratamos desde storage.
  // Decisión: useEffect con [user] garantiza que los datos siempre
  // corresponden al usuario autenticado actual.
  useEffect(() => {
    if (!user) return;
    dispatch({ type:"HYDRATE", payload: hydrateClasses(user.id) });
  }, [user]);

  // EFECTO DE PERSISTENCIA
  // Cada vez que cambian las clases, guardamos los IDs donde el usuario
  // está inscrito. Guardamos solo IDs (no objetos completos) para
  // mantener localStorage limpio y evitar inconsistencias.
  useEffect(() => {
    if (!user) return;
    const enrolledIds = state.classes
      .filter(c => c.enrolled.includes(user.id))
      .map(c => c.id);
    PersistenceService.save(user.id, enrolledIds);
  }, [state.classes, user]);

  const toggleBooking = useCallback((classId, userId) => {
    try {
      dispatch({ type:"TOGGLE_BOOKING", payload: ClassService.toggleBooking(state.classes, classId, userId) });
    } catch(e) {
      dispatch({ type:"SET_ERROR", payload: e.message });
      setTimeout(() => dispatch({ type:"CLEAR_ERROR" }), 3000);
    }
  }, [state.classes]);

  return <GymContext.Provider value={{ ...state, toggleBooking }}>{children}</GymContext.Provider>;
}
const useGym = () => useContext(GymContext);

const ThemeContext = createContext(null);
function ThemeProvider({ children }) {
  const [dark, setDark] = useState(true);
  return <ThemeContext.Provider value={{ dark, toggle:()=>setDark(d=>!d) }}>{children}</ThemeContext.Provider>;
}
const useTheme = () => useContext(ThemeContext);

// ════════════════════════════════════════════════════════════
//  DESIGN TOKENS
// ════════════════════════════════════════════════════════════
const tokens = (dark) => ({
  bg:          dark ? "#0A0A0F" : "#F2F1ED",
  surface:     dark ? "#12121A" : "#FFFFFF",
  surface2:    dark ? "#1C1C28" : "#EAEAE4",
  border:      dark ? "#272736" : "#DDDDD5",
  text:        dark ? "#EEEAE0" : "#18181F",
  textSub:     dark ? "#807A9A" : "#6B6778",
  accent:      "#FF3D5A",
  accentB:     "#7C3AED",
  success:     "#10B981",
  warning:     "#F59E0B",
  fontDisplay: "'Bebas Neue', sans-serif",
  fontBody:    "'DM Sans', sans-serif",
});

const CATEGORY_ICONS = { cardio:"🔴", strength:"⚡", flexibility:"🌿", combat:"🥊" };
const CATEGORY_LABELS = { cardio:"Cardio", strength:"Fuerza", flexibility:"Flexibilidad", combat:"Combat" };

// ════════════════════════════════════════════════════════════
//  SHARED COMPONENTS
// ════════════════════════════════════════════════════════════

function Btn({ children, onClick, variant="primary", disabled, fullWidth, small, style:xtra={} }) {
  const { dark } = useTheme(); const t = tokens(dark);
  const variants = {
    primary:   { background:t.accent,   color:"#fff" },
    secondary: { background:t.surface2, color:t.text,    border:`1px solid ${t.border}` },
    ghost:     { background:"transparent", color:t.textSub, border:`1px solid ${t.border}` },
    success:   { background:t.success,  color:"#fff" },
    danger:    { background:"#2A1219",  color:"#FF4D6D", border:"1px solid #3D1A22" },
  };
  return (
    <button onClick={!disabled ? onClick : undefined} style={{
      border:"none", borderRadius:14, cursor:disabled?"not-allowed":"pointer",
      fontFamily:t.fontBody, fontWeight:700, letterSpacing:"0.03em",
      transition:"all 0.18s ease", opacity:disabled?0.4:1,
      width:fullWidth?"100%":"auto",
      padding:small?"8px 16px":"14px 24px",
      fontSize:small?"0.78rem":"0.92rem",
      ...variants[variant], ...xtra,
    }}>{children}</button>
  );
}

function Input({ label, value, onChange, type="text", placeholder, error }) {
  const { dark } = useTheme(); const t = tokens(dark);
  return (
    <div style={{ marginBottom:16 }}>
      {label && <label style={{ display:"block", marginBottom:6, fontSize:"0.75rem", color:t.textSub, fontFamily:t.fontBody, letterSpacing:"0.07em", textTransform:"uppercase" }}>{label}</label>}
      <input type={type} value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder} style={{
        width:"100%", padding:"13px 16px", borderRadius:12,
        background:t.surface2, border:`1px solid ${error?t.accent:t.border}`,
        color:t.text, fontFamily:t.fontBody, fontSize:"0.95rem",
        outline:"none", boxSizing:"border-box",
      }} />
      {error && <p style={{ margin:"4px 0 0", fontSize:"0.73rem", color:t.accent, fontFamily:t.fontBody }}>{error}</p>}
    </div>
  );
}

function Toast({ message, type="error" }) {
  const { dark } = useTheme(); const t = tokens(dark);
  const colors = { error:t.accent, success:t.success, info:t.accentB };
  return (
    <div style={{
      position:"fixed", bottom:88, left:"50%", transform:"translateX(-50%)",
      background:t.surface, border:`1px solid ${colors[type]}55`,
      borderLeft:`3px solid ${colors[type]}`,
      padding:"12px 20px", borderRadius:12, zIndex:9999,
      fontFamily:t.fontBody, fontSize:"0.85rem", color:t.text,
      boxShadow:"0 8px 32px #00000066", maxWidth:320, textAlign:"center",
      animation:"toastIn 0.3s ease",
    }}>{message}</div>
  );
}

// ════════════════════════════════════════════════════════════
//  MIS RESERVAS — Drawer (bottom-sheet)
//  Decisión de diseño: bottom-sheet en lugar de página nueva
//  → No interrumpe el flujo, se puede cerrar con swipe/tap fuera
//  → Muestra el contenido en contexto, sin perder el estado de la lista
// ════════════════════════════════════════════════════════════

function BookingsDrawer({ onClose }) {
  const { dark } = useTheme(); const t = tokens(dark);
  const { user } = useAuth();
  const { classes, toggleBooking } = useGym();
  const [expandedId, setExpandedId]   = useState(null); // clase expandida
  const [confirmingId, setConfirmingId] = useState(null); // clase en proceso de confirmar cancelación

  // Derivamos las reservas del usuario directamente del estado global
  const myBookings = useMemo(() =>
    classes
      .filter(c => c.enrolled.includes(user.id))
      .sort((a, b) => {
        // Ordenar por día de la semana, luego por hora
        const days = ["Lun","Mar","Mié","Jue","Vie","Sáb","Dom"];
        const dayDiff = days.indexOf(a.day) - days.indexOf(b.day);
        return dayDiff !== 0 ? dayDiff : a.time.localeCompare(b.time);
      }),
    [classes, user.id]
  );

  function handleCancel(classId) {
    toggleBooking(classId, user.id);
    setExpandedId(null);
    setConfirmingId(null);
    // Si era la última reserva, el drawer mostrará el estado vacío automáticamente
  }

  return (
    // Overlay: clic fuera cierra el drawer
    <div
      onClick={onClose}
      style={{
        position:"fixed", inset:0, background:"#00000088",
        zIndex:200, display:"flex", alignItems:"flex-end", justifyContent:"center",
        animation:"fadeIn 0.2s ease",
      }}
    >
      {/* Sheet: stopPropagation evita que el clic en el contenido cierre el drawer */}
      <div
        onClick={e => e.stopPropagation()}
        style={{
          width:"100%", maxWidth:430,
          background:t.surface, borderRadius:"24px 24px 0 0",
          border:`1px solid ${t.border}`, borderBottom:"none",
          maxHeight:"82vh", display:"flex", flexDirection:"column",
          animation:"slideUp 0.32s cubic-bezier(0.32,0.72,0,1)",
          overflow:"hidden",
        }}
      >
        {/* Handle + header */}
        <div style={{ padding:"12px 20px 0", flexShrink:0 }}>
          {/* Drag handle visual */}
          <div style={{ width:36, height:4, borderRadius:2, background:t.border, margin:"0 auto 16px" }} />
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:16 }}>
            <div>
              <h2 style={{ margin:0, fontFamily:t.fontDisplay, fontSize:"1.7rem", color:t.text, letterSpacing:"0.04em" }}>
                MIS RESERVAS
              </h2>
              <p style={{ margin:"2px 0 0", fontSize:"0.75rem", color:t.textSub, fontFamily:t.fontBody }}>
                {myBookings.length === 0
                  ? "Sin reservas activas"
                  : `${myBookings.length} clase${myBookings.length > 1 ? "s" : ""} reservada${myBookings.length > 1 ? "s" : ""}`}
              </p>
            </div>
            <button
              onClick={onClose}
              style={{ background:t.surface2, border:`1px solid ${t.border}`, borderRadius:12, width:36, height:36, cursor:"pointer", color:t.textSub, fontSize:"1.1rem", display:"flex", alignItems:"center", justifyContent:"center" }}
            >×</button>
          </div>
          {/* Separador */}
          <div style={{ height:1, background:t.border, margin:"0 -20px" }} />
        </div>

        {/* Lista scrolleable */}
        <div style={{ overflowY:"auto", flex:1, padding:"12px 20px 32px" }}>
          {myBookings.length === 0 ? (
            <div style={{ textAlign:"center", padding:"48px 0" }}>
              <p style={{ fontSize:"2.5rem", margin:"0 0 12px" }}>📋</p>
              <p style={{ color:t.textSub, fontFamily:t.fontBody, fontSize:"0.9rem", margin:0 }}>
                No tienes clases reservadas.
              </p>
              <p style={{ color:t.textSub, fontFamily:t.fontBody, fontSize:"0.8rem", marginTop:4 }}>
                Ve a la pestaña Clases para reservar.
              </p>
            </div>
          ) : myBookings.map(c => {
            const isExpanded   = expandedId === c.id;
            const isConfirming = confirmingId === c.id;

            return (
              <div key={c.id} style={{ marginBottom:10 }}>
                {/* Fila principal — clicable para expandir */}
                <button
                  onClick={() => {
                    setExpandedId(isExpanded ? null : c.id);
                    setConfirmingId(null); // reset confirmación al plegar
                  }}
                  style={{
                    width:"100%", background:isExpanded ? t.surface2 : t.surface,
                    border:`1px solid ${isExpanded ? c.color+"55" : t.border}`,
                    borderLeft:`3px solid ${c.color}`,
                    borderRadius:isExpanded ? "16px 16px 0 0" : 16,
                    padding:"14px 16px", cursor:"pointer",
                    display:"flex", alignItems:"center", gap:12,
                    textAlign:"left", transition:"all 0.2s ease",
                  }}
                >
                  {/* Icono categoría */}
                  <div style={{
                    width:40, height:40, borderRadius:12, flexShrink:0,
                    background:`${c.color}18`, border:`1px solid ${c.color}33`,
                    display:"flex", alignItems:"center", justifyContent:"center", fontSize:"1.1rem",
                  }}>
                    {CATEGORY_ICONS[c.category]}
                  </div>

                  {/* Info principal */}
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ display:"flex", alignItems:"center", gap:6 }}>
                      <span style={{ fontFamily:t.fontDisplay, fontSize:"1.1rem", color:t.text, letterSpacing:"0.03em" }}>
                        {c.name}
                      </span>
                      <span style={{ fontSize:"0.58rem", background:`${c.color}22`, color:c.color, border:`1px solid ${c.color}44`, borderRadius:8, padding:"2px 7px", fontWeight:700, letterSpacing:"0.06em", flexShrink:0 }}>
                        {c.day}
                      </span>
                    </div>
                    <p style={{ margin:"2px 0 0", fontSize:"0.73rem", color:t.textSub, fontFamily:t.fontBody }}>
                      {c.time} · {c.duration} min · {c.instructor}
                    </p>
                  </div>

                  {/* Chevron animado */}
                  <span style={{
                    color:t.textSub, fontSize:"0.9rem", flexShrink:0,
                    transition:"transform 0.22s ease",
                    transform: isExpanded ? "rotate(180deg)" : "rotate(0deg)",
                  }}>▾</span>
                </button>

                {/* Panel expandido con detalle + cancelar */}
                {isExpanded && (
                  <div style={{
                    background:t.surface2, border:`1px solid ${c.color}33`,
                    borderTop:`1px solid ${t.border}`,
                    borderRadius:"0 0 16px 16px", padding:"14px 16px",
                    animation:"expandDown 0.22s ease",
                  }}>
                    {/* Detalles en grid */}
                    <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:"8px 16px", marginBottom:14 }}>
                      {[
                        { label:"Categoría",   value:CATEGORY_LABELS[c.category] },
                        { label:"Instructor",  value:c.instructor                 },
                        { label:"Hora inicio", value:c.time                       },
                        { label:"Duración",    value:`${c.duration} min`          },
                        { label:"Aforo",       value:`${c.enrolled.length} / ${c.capacity}` },
                        { label:"Plazas lib.", value:c.availableSpots.toString()  },
                      ].map(({ label, value }) => (
                        <div key={label}>
                          <p style={{ margin:0, fontSize:"0.62rem", color:t.textSub, fontFamily:t.fontBody, textTransform:"uppercase", letterSpacing:"0.08em" }}>{label}</p>
                          <p style={{ margin:"2px 0 0", fontSize:"0.82rem", color:t.text, fontFamily:t.fontBody, fontWeight:600 }}>{value}</p>
                        </div>
                      ))}
                    </div>

                    {/* Barra de ocupación */}
                    <div style={{ marginBottom:14 }}>
                      <div style={{ display:"flex", gap:2, flexWrap:"wrap" }}>
                        {Array.from({ length:c.capacity }).map((_,i) => (
                          <div key={i} style={{
                            width:8, height:8, borderRadius:2,
                            background: i < c.enrolled.length ? c.color : t.border,
                            transition:"background 0.3s",
                          }} />
                        ))}
                      </div>
                    </div>

                    {/* Zona de cancelación */}
                    {!isConfirming ? (
                      <Btn
                        fullWidth small variant="danger"
                        onClick={() => setConfirmingId(c.id)}
                      >
                        Cancelar reserva
                      </Btn>
                    ) : (
                      <div style={{
                        background:"#1A080D", border:"1px solid #3D1020",
                        borderRadius:12, padding:"12px 14px",
                      }}>
                        <p style={{ margin:"0 0 10px", fontSize:"0.8rem", color:"#FF6B6B", fontFamily:t.fontBody, fontWeight:600 }}>
                          ¿Seguro que quieres cancelar {c.name}?
                        </p>
                        <div style={{ display:"flex", gap:8 }}>
                          <Btn
                            small variant="danger"
                            style={{ flex:1 }}
                            onClick={() => handleCancel(c.id)}
                          >
                            Sí, cancelar
                          </Btn>
                          <Btn
                            small variant="ghost"
                            style={{ flex:1 }}
                            onClick={() => setConfirmingId(null)}
                          >
                            Mantener
                          </Btn>
                        </div>
                      </div>
                    )}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

