function NavBar({ screen, onNavigate, onOpenBookings }) {
  const { dark, toggle } = useTheme(); const t = tokens(dark);
  const { logout } = useAuth();
  const { user }   = useAuth();
  const { classes } = useGym();

  const bookingCount = classes.filter(c => c.enrolled.includes(user?.id)).length;

  const items = [
    { id:"dashboard",   icon:"⊞", label:"Inicio"  },
    { id:"classes",     icon:"◈", label:"Clases"   },
    { id:"trainings",   icon:"🏋️", label:"Ejerc."  },
  ];
  return (
    <nav style={{
      position:"fixed", bottom:0, left:"50%", transform:"translateX(-50%)",
      width:"100%", maxWidth:430,
      background:`${t.surface}F0`, backdropFilter:"blur(20px)",
      borderTop:`1px solid ${t.border}`, display:"flex",
      padding:"10px 12px 20px", gap:6, zIndex:100, boxSizing:"border-box",
    }}>
      {items.map(item => (
        <button key={item.id} onClick={() => onNavigate(item.id)} style={{
          flex:1, background:screen===item.id ? `${t.accent}18` : "transparent",
          border:`1px solid ${screen===item.id ? `${t.accent}44` : "transparent"}`,
          borderRadius:14, padding:"10px 6px",
          display:"flex", flexDirection:"column", alignItems:"center", gap:3,
          cursor:"pointer", transition:"all 0.2s",
        }}>
          <span style={{ fontSize:"1rem", filter:screen===item.id?"none":"grayscale(1) opacity(0.45)" }}>{item.icon}</span>
          <span style={{ fontSize:"0.58rem", fontFamily:t.fontBody, fontWeight:700, color:screen===item.id?t.accent:t.textSub, letterSpacing:"0.07em", textTransform:"uppercase" }}>{item.label}</span>
        </button>
      ))}

      {/* Mis Reservas con badge */}
      <button onClick={onOpenBookings} style={{
        position:"relative", flex:1,
        background:t.surface2, border:`1px solid ${t.border}`,
        borderRadius:14, padding:"10px 6px",
        display:"flex", flexDirection:"column", alignItems:"center", gap:3,
        cursor:"pointer", transition:"all 0.2s",
      }}>
        <span style={{ fontSize:"1rem" }}>📋</span>
        <span style={{ fontSize:"0.58rem", fontFamily:t.fontBody, fontWeight:700, color:t.textSub, letterSpacing:"0.07em", textTransform:"uppercase" }}>Reservas</span>
        {bookingCount > 0 && (
          <span style={{
            position:"absolute", top:4, right:4,
            background:t.accent, color:"#fff", borderRadius:"50%",
            width:15, height:15, fontSize:"0.55rem", fontWeight:700,
            display:"flex", alignItems:"center", justifyContent:"center",
            fontFamily:t.fontBody,
          }}>{bookingCount}</span>
        )}
      </button>

      <button onClick={toggle} style={{ background:t.surface2, border:`1px solid ${t.border}`, borderRadius:14, padding:"10px 10px", cursor:"pointer", fontSize:"0.95rem" }}>
        {dark ? "☀️" : "🌙"}
      </button>
      <button onClick={logout} style={{ background:"transparent", border:`1px solid ${t.border}`, borderRadius:14, padding:"10px 8px", cursor:"pointer", color:t.textSub, fontSize:"0.65rem", fontFamily:t.fontBody }}>
        Salir
      </button>
    </nav>
  );
}

// ════════════════════════════════════════════════════════════
//  FEATURES / AUTH — LoginScreen
// ════════════════════════════════════════════════════════════

function LoginScreen() {
  const { dark } = useTheme(); const t = tokens(dark);
  const { login, register, loading, error } = useAuth();
  const [mode, setMode] = useState("login");
  const [form, setForm] = useState({ name:"", email:"", password:"" });
  const [fieldErrors, setFieldErrors] = useState({});
  const set = (key) => (val) => setForm(f => ({ ...f, [key]:val }));

  function validate() {
    const e = {};
    if (mode === "register" && !form.name.trim()) e.name = "Requerido";
    if (!form.email.includes("@")) e.email = "Email inválido";
    if (form.password.length < 4) e.password = "Mínimo 4 caracteres";
    setFieldErrors(e);
    return !Object.keys(e).length;
  }
  function handleSubmit() {
    if (!validate()) return;
    if (mode === "login") login(form.email, form.password);
    else register(form.name, form.email, form.password);
  }

  return (
    <div style={{ minHeight:"100vh", background:t.bg, display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", padding:"0 24px", fontFamily:t.fontBody }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=DM+Sans:ital,opsz,wght@0,9..40,400;0,9..40,500;0,9..40,700&display=swap');
        * { box-sizing:border-box; }
        input::placeholder { color:${t.textSub}66; }
        @keyframes toastIn    { from{opacity:0;transform:translateX(-50%) translateY(12px)} to{opacity:1;transform:translateX(-50%) translateY(0)} }
        @keyframes fadeUp     { from{opacity:0;transform:translateY(20px)} to{opacity:1;transform:translateY(0)} }
        @keyframes fadeIn     { from{opacity:0} to{opacity:1} }
        @keyframes slideUp    { from{transform:translateY(100%)} to{transform:translateY(0)} }
        @keyframes expandDown { from{opacity:0;transform:scaleY(0.8);transform-origin:top} to{opacity:1;transform:scaleY(1)} }
        @keyframes pulse      { 0%,100%{box-shadow:0 0 0 0 rgba(255,61,90,0.4)} 50%{box-shadow:0 0 0 14px rgba(255,61,90,0)} }
      `}</style>

      <div style={{ textAlign:"center", marginBottom:40, animation:"fadeUp 0.5s ease" }}>
        <div style={{ width:72, height:72, borderRadius:22, background:`linear-gradient(135deg,#FF3D5A,#7C3AED)`, display:"flex", alignItems:"center", justifyContent:"center", margin:"0 auto 16px", fontSize:"1.8rem", animation:"pulse 2.5s infinite" }}>⚡</div>
        <h1 style={{ fontFamily:t.fontDisplay, fontSize:"3.2rem", color:t.text, margin:0, letterSpacing:"0.06em" }}>IRON GYM</h1>
        <p style={{ color:t.textSub, margin:"4px 0 0", fontSize:"0.83rem" }}>Tu centro de entrenamiento · Barcelona</p>
      </div>

      <div style={{ width:"100%", maxWidth:380, background:t.surface, borderRadius:24, padding:28, border:`1px solid ${t.border}`, animation:"fadeUp 0.5s ease 0.1s both" }}>
        <div style={{ display:"flex", background:t.surface2, borderRadius:14, padding:4, marginBottom:24, border:`1px solid ${t.border}` }}>
          {["login","register"].map(m => (
            <button key={m} onClick={()=>{ setMode(m); setFieldErrors({}); }} style={{
              flex:1, padding:"10px", borderRadius:11, border:"none",
              background:mode===m ? "#FF3D5A" : "transparent",
              color:mode===m ? "#fff" : t.textSub,
              fontFamily:t.fontBody, fontWeight:700, fontSize:"0.82rem",
              cursor:"pointer", transition:"all 0.2s",
            }}>{m==="login" ? "Iniciar Sesión" : "Registrarse"}</button>
          ))}
        </div>

        {mode==="register" && <Input label="Nombre" value={form.name} onChange={set("name")} placeholder="Tu nombre" error={fieldErrors.name} />}
        <Input label="Email" value={form.email} onChange={set("email")} type="email" placeholder="correo@email.com" error={fieldErrors.email} />
        <Input label="Contraseña" value={form.password} onChange={set("password")} type="password" placeholder="••••••••" error={fieldErrors.password} />

        {error && <p style={{ color:"#FF3D5A", fontSize:"0.8rem", margin:"0 0 16px", textAlign:"center" }}>{error}</p>}

        <Btn fullWidth onClick={handleSubmit} disabled={loading}>
          {loading ? "⏳ Verificando..." : mode==="login" ? "Entrar al Gym" : "Crear cuenta"}
        </Btn>

        <div style={{ marginTop:16, padding:"10px 14px", background:"#7C3AED14", borderRadius:10, border:"1px solid #7C3AED30" }}>
          <p style={{ margin:0, fontSize:"0.72rem", color:t.textSub, lineHeight:1.6 }}>
            <strong style={{ color:"#7C3AED" }}>Demo:</strong> usa{" "}
            <code style={{ color:t.text, background:t.surface2, padding:"1px 5px", borderRadius:4 }}>alex@gym.com</code> / <code style={{ color:t.text, background:t.surface2, padding:"1px 5px", borderRadius:4 }}>gym123</code>
          </p>
        </div>
      </div>
    </div>
  );
}

// ════════════════════════════════════════════════════════════
//  FEATURES / DASHBOARD
// ════════════════════════════════════════════════════════════

function MiniQR({ data }) {
  const grid = useMemo(() => {
    const seed = data.split("").reduce((a,c)=>a+c.charCodeAt(0),0);
    return Array.from({ length:49 },(_,i) => {
      const r=Math.floor(i/7), c=i%7;
      if ((r<2&&c<2)||(r<2&&c>4)||(r>4&&c<2)) return true;
      return ((seed*(i+1)*2654435761)%97)>45;
    });
  },[data]);
  return (
    <div style={{ display:"inline-grid", gridTemplateColumns:"repeat(7,1fr)", gap:2, padding:12, background:"#fff", borderRadius:12 }}>
      {grid.map((on,i) => <div key={i} style={{ width:8, height:8, borderRadius:1, background:on?"#0A0A0F":"#fff" }} />)}
    </div>
  );
}

const PLAN_META = {
  basic:   { label:"Basic",   color:"#6B7280", perks:["Sala máquinas","Vestuarios"] },
  premium: { label:"Premium", color:"#F59E0B", perks:["Sala máquinas","Clases grupales","Vestuarios premium"] },
  elite:   { label:"Elite",   color:"#7C3AED", perks:["Todo ilimitado","Nutricionista","Fisioterapeuta"] },
};

function DashboardScreen({ onOpenBookings }) {
  const { dark } = useTheme(); const t = tokens(dark);
  const { user } = useAuth();
  const { classes } = useGym();

  const plan = PLAN_META[user.plan];
  const userClasses = classes.filter(c => c.enrolled.includes(user.id));
  const daysGoal = 20;
  const progress = Math.min((user.trainingDays / daysGoal)*100, 100);

  return (
    <div style={{ minHeight:"100vh", background:t.bg, padding:"0 16px 100px", fontFamily:t.fontBody }}>
      <div style={{ paddingTop:56, marginBottom:24 }}>
        <p style={{ margin:"0 0 2px", fontSize:"0.8rem", color:t.textSub }}>Bienvenido de vuelta</p>
        <h1 style={{ margin:0, fontFamily:t.fontDisplay, fontSize:"2.6rem", color:t.text, letterSpacing:"0.04em" }}>
          {user.name.split(" ")[0].toUpperCase()} 👋
        </h1>
      </div>

      {/* QR Card */}
      <div style={{
        background:dark?"linear-gradient(135deg,#1A0E22,#0E1826)":"linear-gradient(135deg,#F0E8FF,#E8F0FF)",
        border:`1px solid ${t.border}`, borderRadius:24, padding:22, marginBottom:14,
        display:"flex", gap:20, alignItems:"center",
      }}>
        <div style={{ flexShrink:0 }}>
          <MiniQR data={user.qrCode} />
          <p style={{ margin:"8px 0 0", fontSize:"0.6rem", color:t.textSub, textAlign:"center", letterSpacing:"0.12em", textTransform:"uppercase" }}>Acceso Gym</p>
        </div>
        <div style={{ flex:1 }}>
          <span style={{ display:"inline-block", padding:"3px 10px", borderRadius:20, background:`${plan.color}22`, color:plan.color, border:`1px solid ${plan.color}44`, fontSize:"0.68rem", fontWeight:700, textTransform:"uppercase" }}>✦ {plan.label}</span>
          <h3 style={{ margin:"10px 0 4px", color:t.text, fontFamily:t.fontDisplay, fontSize:"1.4rem" }}>{user.name}</h3>
          <p style={{ margin:"0 0 10px", fontSize:"0.73rem", color:t.textSub }}>Desde {user.joinDate}</p>
          {plan.perks.map(p => <p key={p} style={{ margin:"2px 0", fontSize:"0.71rem", color:t.textSub }}><span style={{ color:t.success }}>✓</span> {p}</p>)}
        </div>
      </div>

      {/* Stats */}
      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:12, marginBottom:14 }}>
        <div style={{ background:t.surface, border:`1px solid ${t.border}`, borderRadius:20, padding:20 }}>
          <p style={{ margin:"0 0 4px", fontSize:"0.68rem", color:t.textSub, textTransform:"uppercase", letterSpacing:"0.08em" }}>Días este mes</p>
          <div style={{ display:"flex", alignItems:"baseline", gap:4 }}>
            <span style={{ fontFamily:t.fontDisplay, fontSize:"3rem", color:t.accent, lineHeight:1 }}>{user.trainingDays}</span>
            <span style={{ fontSize:"0.78rem", color:t.textSub }}>/ {daysGoal}</span>
          </div>
          <div style={{ marginTop:10, height:5, background:t.surface2, borderRadius:3, overflow:"hidden" }}>
            <div style={{ height:"100%", width:`${progress}%`, background:`linear-gradient(90deg,#FF3D5A,#7C3AED)`, borderRadius:3 }} />
          </div>
          <p style={{ margin:"5px 0 0", fontSize:"0.67rem", color:t.textSub }}>{Math.round(progress)}% del objetivo</p>
        </div>

        {/* Widget Mis Reservas — clicable para abrir el drawer */}
        <button
          onClick={onOpenBookings}
          style={{
            background:t.surface, border:`1px solid ${t.border}`,
            borderRadius:20, padding:20, cursor:"pointer",
            textAlign:"left", transition:"all 0.2s",
          }}
        >
          <p style={{ margin:"0 0 8px", fontSize:"0.68rem", color:t.textSub, textTransform:"uppercase", letterSpacing:"0.08em" }}>
            Mis reservas
          </p>
          {userClasses.length === 0 ? (
            <p style={{ margin:0, fontSize:"0.82rem", color:t.textSub, lineHeight:1.4 }}>Sin reservas activas</p>
          ) : (
            <>
              {userClasses.slice(0,3).map(c => (
                <div key={c.id} style={{ marginBottom:7 }}>
                  <div style={{ display:"flex", alignItems:"center", gap:6 }}>
                    <div style={{ width:7, height:7, borderRadius:"50%", background:c.color }} />
                    <span style={{ fontSize:"0.8rem", color:t.text, fontWeight:600 }}>{c.name}</span>
                  </div>
                  <p style={{ margin:"1px 0 0 13px", fontSize:"0.68rem", color:t.textSub }}>{c.day} · {c.time}</p>
                </div>
              ))}
              {userClasses.length > 3 && (
                <p style={{ margin:0, fontSize:"0.7rem", color:"#7C3AED" }}>+{userClasses.length-3} más →</p>
              )}
              <p style={{ margin:"8px 0 0", fontSize:"0.68rem", color:"#7C3AED", fontWeight:600 }}>
                Ver todas →
              </p>
            </>
          )}
        </button>
      </div>

      <div style={{ background:dark?"#12080F":"#FFF0F3", border:"1px solid #FF3D5A33", borderRadius:18, padding:"14px 18px" }}>
        <p style={{ margin:0, fontFamily:t.fontDisplay, fontSize:"1.05rem", color:t.accent, letterSpacing:"0.05em" }}>
          {user.trainingDays>=15 ? "🔥 ¡RACHA IMPARABLE! SIGUE ASÍ" :
           user.trainingDays>=8  ? "💪 BUEN RITMO — NO PARES AHORA" :
                                   "⚡ ESTA SEMANA, DA EL PRIMER PASO"}
        </p>
      </div>
    </div>
  );
}

// ════════════════════════════════════════════════════════════
//  FEATURES / CLASSES
// ════════════════════════════════════════════════════════════

function ClassCard({ gymClass, isEnrolled, onToggle, userId }) {
  const { dark } = useTheme(); const t = tokens(dark);
  const [localLoading, setLocalLoading] = useState(false);
  const isFull = gymClass.availableSpots <= 0 && !isEnrolled;
  const spotsColor = gymClass.availableSpots<=2 ? t.accent : gymClass.availableSpots<=6 ? t.warning : t.success;

  function handleClick() {
    setLocalLoading(true);
    setTimeout(() => { onToggle(gymClass.id, userId); setLocalLoading(false); }, 300);
  }

  return (
    <div style={{
      background:t.surface,
      border:`1px solid ${isEnrolled ? gymClass.color+"55" : t.border}`,
      borderLeft:`3px solid ${isEnrolled ? gymClass.color : "transparent"}`,
      borderRadius:18, padding:18, marginBottom:10,
      transition:"all 0.2s ease",
      boxShadow:isEnrolled ? `0 2px 16px ${gymClass.color}18` : "none",
    }}>
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", gap:12 }}>
        <div style={{ flex:1 }}>
          <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:5, flexWrap:"wrap" }}>
            <span>{CATEGORY_ICONS[gymClass.category]}</span>
            <h3 style={{ margin:0, fontFamily:t.fontDisplay, fontSize:"1.3rem", color:t.text, letterSpacing:"0.04em" }}>{gymClass.name}</h3>
            {isEnrolled && (
              <span style={{ fontSize:"0.58rem", background:`${gymClass.color}22`, color:gymClass.color, border:`1px solid ${gymClass.color}44`, borderRadius:10, padding:"2px 8px", fontWeight:700 }}>✓ RESERVADO</span>
            )}
          </div>
          <div style={{ display:"flex", gap:14, flexWrap:"wrap", marginBottom:10 }}>
            <span style={{ fontSize:"0.76rem", color:t.textSub }}>👤 {gymClass.instructor}</span>
            <span style={{ fontSize:"0.76rem", color:t.textSub }}>🕐 {gymClass.time}</span>
            <span style={{ fontSize:"0.76rem", color:t.textSub }}>⏱ {gymClass.duration} min</span>
          </div>
          <div style={{ display:"flex", alignItems:"center", gap:8 }}>
            <div style={{ display:"flex", gap:2, flexWrap:"wrap", maxWidth:160 }}>
              {Array.from({ length:gymClass.capacity }).map((_,i) => (
                <div key={i} style={{ width:7, height:7, borderRadius:2, background:i<gymClass.enrolled.length?gymClass.color:t.surface2, border:`1px solid ${i<gymClass.enrolled.length?gymClass.color:t.border}`, transition:"background 0.4s ease" }} />
              ))}
            </div>
            <span style={{ fontSize:"0.7rem", color:spotsColor, fontWeight:700 }}>
              {isFull ? "COMPLETO" : `${gymClass.availableSpots} libre${gymClass.availableSpots!==1?"s":""}`}
            </span>
          </div>
        </div>
        <div style={{ flexShrink:0 }}>
          <Btn small variant={isEnrolled?"danger":isFull?"ghost":"primary"} disabled={isFull||localLoading} onClick={handleClick} style={{ minWidth:96 }}>
            {localLoading ? "..." : isEnrolled ? "Cancelar" : isFull ? "Completo" : "Reservar"}
          </Btn>
        </div>
      </div>
    </div>
  );
}

function ClassesScreen({ onOpenBookings }) {
  const { dark } = useTheme(); const t = tokens(dark);
  const { user } = useAuth();
  const { classes, toggleBooking, bookingError } = useGym();

  const DAYS = ["Lun","Mar","Mié","Jue","Vie"];
  const [selectedDay, setSelectedDay] = useState("Lun");
  const [filterCategory, setFilterCategory] = useState("all");

  const filtered = useMemo(() =>
    classes
      .filter(c => c.day === selectedDay)
      .filter(c => filterCategory === "all" || c.category === filterCategory)
      .sort((a,b) => a.time.localeCompare(b.time)),
    [classes, selectedDay, filterCategory]
  );

  const totalReservas = classes.filter(c => c.enrolled.includes(user.id)).length;

  const CATEGORIES = [
    { id:"all",         label:"Todas",  emoji:"" },
    { id:"cardio",      label:"Cardio", emoji:"🔴" },
    { id:"strength",    label:"Fuerza", emoji:"⚡" },
    { id:"flexibility", label:"Flex",   emoji:"🌿" },
    { id:"combat",      label:"Combat", emoji:"🥊" },
  ];

  return (
    <div style={{ minHeight:"100vh", background:t.bg, paddingBottom:100, fontFamily:t.fontBody }}>
      {bookingError && <Toast message={`⚠️ ${bookingError}`} type="error" />}

      <div style={{ position:"sticky", top:0, zIndex:50, background:`${t.surface}F5`, backdropFilter:"blur(20px)", borderBottom:`1px solid ${t.border}`, padding:"20px 16px 0" }}>
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:16 }}>
          <h1 style={{ margin:0, fontFamily:t.fontDisplay, fontSize:"2rem", color:t.text, letterSpacing:"0.05em" }}>CLASES</h1>
          {/* Badge clicable → abre el drawer */}
          {totalReservas > 0 && (
            <button
              onClick={onOpenBookings}
              style={{
                fontSize:"0.72rem", background:"#7C3AED18", color:"#7C3AED",
                border:"1px solid #7C3AED33", borderRadius:20, padding:"4px 12px",
                fontWeight:700, fontFamily:t.fontBody, cursor:"pointer",
                transition:"all 0.2s",
              }}
            >
              {totalReservas} reserva{totalReservas>1?"s":""} →
            </button>
          )}
        </div>

        <div style={{ display:"flex", gap:6, marginBottom:10, overflowX:"auto", paddingBottom:2 }}>
          {DAYS.map(day => (
            <button key={day} onClick={()=>setSelectedDay(day)} style={{
              padding:"8px 18px", borderRadius:12, flexShrink:0,
              background:selectedDay===day ? t.accent : t.surface2,
              border:`1px solid ${selectedDay===day?"transparent":t.border}`,
              color:selectedDay===day ? "#fff" : t.textSub,
              fontFamily:t.fontBody, fontWeight:700, fontSize:"0.82rem",
              cursor:"pointer", transition:"all 0.2s",
            }}>{day}</button>
          ))}
        </div>

        <div style={{ display:"flex", gap:6, marginBottom:0, overflowX:"auto", paddingBottom:12 }}>
          {CATEGORIES.map(cat => (
            <button key={cat.id} onClick={()=>setFilterCategory(cat.id)} style={{
              padding:"5px 12px", borderRadius:20, flexShrink:0,
              border:`1px solid ${filterCategory===cat.id?"#7C3AED":t.border}`,
              background:filterCategory===cat.id?"#7C3AED20":"transparent",
              color:filterCategory===cat.id?"#7C3AED":t.textSub,
              fontFamily:t.fontBody, fontWeight:600, fontSize:"0.72rem",
              cursor:"pointer", transition:"all 0.18s",
            }}>{cat.emoji} {cat.label}</button>
          ))}
        </div>
      </div>

      <div style={{ padding:"14px 16px 0" }}>
        {filtered.length === 0 ? (
          <div style={{ textAlign:"center", padding:"60px 20px" }}>
            <p style={{ fontSize:"2.5rem", marginBottom:8 }}>🏋️</p>
            <p style={{ color:t.textSub, fontSize:"0.88rem" }}>No hay clases para este filtro</p>
          </div>
        ) : filtered.map(gymClass => (
          <ClassCard
            key={gymClass.id}
            gymClass={gymClass}
            isEnrolled={gymClass.enrolled.includes(user.id)}
            onToggle={toggleBooking}
            userId={user.id}
          />
        ))}
      </div>
    </div>
  );
}

// ════════════════════════════════════════════════════════════
//  APP ROOT
// ════════════════════════════════════════════════════════════

function AppShell() {
  const { user } = useAuth();
  const [screen, setScreen]             = useState("dashboard");
  const [showBookings, setShowBookings] = useState(false);

  if (!user) return <LoginScreen />;

  return (
    <>
      {screen === "dashboard"  && <DashboardScreen onOpenBookings={() => setShowBookings(true)} />}
      {screen === "classes"    && <ClassesScreen   onOpenBookings={() => setShowBookings(true)} />}
      {screen === "trainings"  && <TrainingsScreen />}

      {showBookings && <BookingsDrawer onClose={() => setShowBookings(false)} />}

      <NavBar
        screen={screen}
        onNavigate={setScreen}
        onOpenBookings={() => setShowBookings(true)}
      />
    </>
  );
}

export default function App() {
  return (
    <ThemeProvider>
      <AuthProvider>
        <GymProvider>
          <AppShell />
        </GymProvider>
      </AuthProvider>
    </ThemeProvider>
  );
}
